package com.mamtrex.hospital.staff;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="staff_members") public class StaffMember extends BaseEntity { private String employeeCode; private String fullName; private String profession; private String licenseNumber; private String department; protected StaffMember(){} public StaffMember(String employeeCode, String fullName, String profession, String licenseNumber, String department){this.employeeCode=employeeCode; this.fullName=fullName; this.profession=profession; this.licenseNumber=licenseNumber; this.department=department;} public String getEmployeeCode(){return employeeCode;} public String getFullName(){return fullName;} public String getProfession(){return profession;} public String getLicenseNumber(){return licenseNumber;} public String getDepartment(){return department;} }
